-- R-ORD1: closed orders older than <orders_days> days: blank the street address and the note (the map-location line lives there)
update orders set customer_note = null, customer_block = null, customer_street = null, customer_building = null, customer_floor = null, customer_flat = null, anonymised_at = now() where anonymised_at is null and (fulfilment_status in ('delivered','cancelled') or (payment_status = 'failed' and fulfilment_status in ('unfulfilled','cancelled'))) and coalesce(fulfilled_at, created_at) < date_sub(now(), interval @orders_days day) and not exists (select 1 from return_requests rr where rr.order_id = orders.id and rr.status not in ('completed','declined','cancelled')) limit 100000000;
set @n_R_ORD1 = row_count();

-- R-ORD2: closed orders older than <identity_days> days (0 = off): blank the name, replace the phone by a keyed pseudonym (or blank it without a salt)
update orders set customer_name = null, customer_phone = if(@salt <> '', concat('p', left(sha2(concat(@salt, right(regexp_replace(customer_phone, '[^0-9]', ''), 8)), 256), 12)), null), customer_note = null, customer_block = null, customer_street = null, customer_building = null, customer_floor = null, customer_flat = null, anonymised_at = coalesce(anonymised_at, now()) where @identity_days > 0 and (fulfilment_status in ('delivered','cancelled') or (payment_status = 'failed' and fulfilment_status in ('unfulfilled','cancelled'))) and coalesce(fulfilled_at, created_at) < date_sub(now(), interval @identity_days day) and (customer_name is not null or customer_phone regexp '^[+0-9]') and not exists (select 1 from return_requests rr where rr.order_id = orders.id and rr.status not in ('completed','declined','cancelled')) limit 100000000;
set @n_R_ORD2 = row_count();

-- R-SUP-1: resolved or closed support tickets older than <support_days> days: blank name, email, phone and subject
update support_tickets set customer_name = '[removed]', customer_email = concat('removed-', id, '@invalid.example'), customer_phone = null, subject = '[removed]', anonymised_at = now(), updated_at = updated_at where anonymised_at is null and status in ('resolved','closed') and coalesce(resolved_at, updated_at) < date_sub(now(), interval @support_days day) limit 100000000;
set @n_R_SUP_1 = row_count();

-- R-SUP-2: messages of those tickets: blank the body and the customer author name
update support_messages m join support_tickets t on t.id = m.ticket_id set m.body = '[removed]', m.author_name = null where t.anonymised_at is not null and (m.body <> '[removed]' or m.author_name is not null);
set @n_R_SUP_2 = row_count();

-- R-RET-1: finished return requests older than <returns_days> days: blank the phone and the customer note
update return_requests set contact_phone = '', customer_note = null, anonymised_at = now(), updated_at = updated_at where anonymised_at is null and status in ('completed','declined','cancelled') and updated_at < date_sub(now(), interval @returns_days day) limit 100000000;
set @n_R_RET_1 = row_count();

-- R-RET-2: events of those requests: blank the note and the customer actor
update return_request_events e join return_requests r on r.id = e.request_id set e.note = null, e.actor = if(e.actor_type = 'customer', null, e.actor) where r.anonymised_at is not null and (e.note is not null or (e.actor_type = 'customer' and e.actor is not null));
set @n_R_RET_2 = row_count();

-- R-OUT-1: warehouse messages SENT more than <outbox_days> days ago: blank the payload (the whole order) and the error text
update fulfilment_outbox set payload = '{"scrubbed":true}', last_error = null where sent_at is not null and sent_at < date_sub(now(), interval @outbox_days day) and payload <> '{"scrubbed":true}' limit 100000000;
set @n_R_OUT_1 = row_count();

-- R-OUT-2: WhatsApp messages SENT more than <outbox_days> days ago: blank the number, the payload and the error text
update whatsapp_outbox set to_e164 = '', payload = '{"scrubbed":true}', last_error = null where sent_at is not null and sent_at < date_sub(now(), interval @outbox_days day) and (payload <> '{"scrubbed":true}' or to_e164 <> '') limit 100000000;
set @n_R_OUT_2 = row_count();

-- R-RES-1: shopper password-reset rows older than <resets_days> days: delete
delete from customer_password_resets where created_at < date_sub(now(), interval @resets_days day) limit 100000000;
set @n_R_RES_1 = row_count();

-- R-RES-2: staff password-reset rows older than <resets_days> days: delete
delete from admin_password_resets where created_at < date_sub(now(), interval @resets_days day) limit 100000000;
set @n_R_RES_2 = row_count();

-- R-LOG-1: admin activity log rows older than <activity_days> days (0 = off): delete
delete from admin_activity_log where @activity_days > 0 and created_at < date_sub(now(), interval @activity_days day) limit 100000000;
